<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --gold: #C9A84C;
    --gold-light: #E8C96E;
    --gold-pale: #F5E9C6;
    --dark: #1A1410;
    --dark-mid: #2C241C;
    --mid: #4A3C2E;
    --text: #F0E8D8;
    --text-muted: #B8A88A;
    --accent: #8B5CF6;
    --accent2: #3B82F6;
    --card-bg: #231D17;
    --border: #3D3028;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Georgia', 'Times New Roman', serif;
    background: var(--dark);
    color: var(--text);
    line-height: 1.7;
  }
  .hero {
    background: linear-gradient(135deg, #1A1410 0%, #2C1810 40%, #1A1410 100%);
    border-bottom: 2px solid var(--gold);
    padding: 60px 40px 50px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute; inset: 0;
    background: radial-gradient(ellipse at 50% 0%, rgba(201,168,76,0.12) 0%, transparent 70%);
  }
  .hero-badge {
    display: inline-block;
    background: var(--gold);
    color: var(--dark);
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 3px;
    text-transform: uppercase;
    padding: 5px 16px;
    border-radius: 2px;
    margin-bottom: 24px;
  }
  .hero h1 {
    font-size: clamp(28px, 5vw, 52px);
    color: var(--gold-light);
    line-height: 1.2;
    margin-bottom: 16px;
    font-weight: normal;
    letter-spacing: -0.5px;
  }
  .hero-sub {
    font-family: 'Arial', sans-serif;
    font-size: 16px;
    color: var(--text-muted);
    max-width: 640px;
    margin: 0 auto;
  }
  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 24px;
  }
  section { padding: 60px 0; border-bottom: 1px solid var(--border); }
  section:last-child { border-bottom: none; }
  h2 {
    font-size: clamp(20px, 3vw, 30px);
    color: var(--gold);
    margin-bottom: 8px;
    font-weight: normal;
    letter-spacing: -0.3px;
  }
  .section-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    color: var(--gold);
    letter-spacing: 3px;
    text-transform: uppercase;
    opacity: 0.7;
    margin-bottom: 6px;
  }
  h3 {
    font-size: 18px;
    color: var(--gold-light);
    margin: 32px 0 12px;
    font-weight: normal;
  }
  p { margin-bottom: 16px; color: var(--text); font-size: 16px; }
  .lead { font-size: 18px; color: var(--text-muted); margin-bottom: 28px; max-width: 800px; }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin: 32px 0;
  }
  .kpi-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-top: 3px solid var(--gold);
    padding: 24px 20px;
    border-radius: 4px;
    text-align: center;
  }
  .kpi-value {
    font-size: 48px;
    font-weight: normal;
    color: var(--gold-light);
    line-height: 1;
    margin-bottom: 8px;
    font-family: 'Georgia', serif;
  }
  .kpi-label {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 4px;
  }
  .kpi-note {
    font-size: 12px;
    color: var(--text-muted);
    opacity: 0.7;
    font-style: italic;
  }

  /* Chart containers */
  .chart-wrap {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 28px;
    margin: 28px 0;
    position: relative;
  }
  .chart-title {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--gold);
    opacity: 0.8;
    margin-bottom: 20px;
  }
  canvas { max-width: 100%; }

  /* Top composers bar */
  .composer-bar-wrap { margin: 12px 0; }
  .composer-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 10px;
    padding: 10px 14px;
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 4px;
    transition: border-color 0.2s;
  }
  .composer-row:hover { border-color: var(--gold); }
  .composer-rank {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: var(--gold);
    width: 24px;
    text-align: right;
    flex-shrink: 0;
    opacity: 0.7;
  }
  .composer-name {
    flex: 0 0 180px;
    font-size: 15px;
    color: var(--text);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .composer-bar-bg {
    flex: 1;
    height: 8px;
    background: var(--border);
    border-radius: 4px;
    overflow: hidden;
  }
  .composer-bar-fill {
    height: 100%;
    border-radius: 4px;
    background: linear-gradient(90deg, var(--gold), var(--gold-light));
  }
  .composer-wins {
    font-family: 'Arial', sans-serif;
    font-size: 14px;
    font-weight: 700;
    color: var(--gold-light);
    width: 24px;
    text-align: right;
    flex-shrink: 0;
  }
  .composer-years {
    font-size: 12px;
    color: var(--text-muted);
    flex: 0 0 180px;
    opacity: 0.7;
  }

  /* Timeline / decade grid */
  .decade-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 14px;
    margin: 28px 0;
  }
  .decade-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 20px;
  }
  .decade-head {
    display: flex;
    align-items: baseline;
    gap: 10px;
    margin-bottom: 12px;
  }
  .decade-label {
    font-size: 22px;
    color: var(--gold);
    font-family: 'Georgia', serif;
  }
  .decade-stat {
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    color: var(--text-muted);
  }
  .decade-entries {
    font-size: 13px;
    color: var(--text-muted);
    line-height: 1.6;
  }
  .decade-entries span.highlight { color: var(--gold-light); }

  /* Era cards */
  .era-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 16px;
    margin: 28px 0;
  }
  .era-card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 22px;
    border-left: 4px solid var(--gold);
  }
  .era-card:nth-child(2) { border-left-color: #3B82F6; }
  .era-card:nth-child(3) { border-left-color: #8B5CF6; }
  .era-card:nth-child(4) { border-left-color: #10B981; }
  .era-title { font-size: 15px; color: var(--gold-light); margin-bottom: 4px; }
  .era-years { font-family: 'Arial', sans-serif; font-size: 11px; color: var(--text-muted); margin-bottom: 14px; }
  .era-stat-row { display: flex; gap: 20px; margin-bottom: 14px; }
  .era-stat { text-align: center; }
  .era-stat-val { font-size: 26px; color: var(--gold); }
  .era-stat-lab { font-family: 'Arial', sans-serif; font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 1px; }
  .era-desc { font-size: 13px; color: var(--text-muted); line-height: 1.6; }

  /* Milestone list */
  .milestone-list { list-style: none; margin: 24px 0; }
  .milestone-list li {
    display: flex;
    gap: 20px;
    padding: 16px 0;
    border-bottom: 1px solid var(--border);
    align-items: flex-start;
  }
  .milestone-list li:last-child { border-bottom: none; }
  .milestone-year {
    font-family: 'Georgia', serif;
    font-size: 20px;
    color: var(--gold);
    flex-shrink: 0;
    width: 52px;
  }
  .milestone-text { font-size: 15px; color: var(--text); }
  .milestone-text strong { color: var(--gold-light); }

  /* Takeaways */
  .takeaway-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: 16px;
    margin: 24px 0;
  }
  .takeaway {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 6px;
    padding: 22px;
  }
  .takeaway-num {
    font-size: 36px;
    color: var(--gold);
    opacity: 0.3;
    line-height: 1;
    font-family: 'Georgia', serif;
    margin-bottom: 10px;
  }
  .takeaway-title { font-size: 15px; color: var(--gold-light); margin-bottom: 8px; }
  .takeaway-body { font-size: 14px; color: var(--text-muted); line-height: 1.6; }

  /* Footer */
  footer {
    text-align: center;
    padding: 32px 24px;
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: var(--text-muted);
    opacity: 0.6;
    border-top: 1px solid var(--border);
  }

  /* Timeline scatter SVG wrapper */
  .timeline-svg-wrap {
    overflow-x: auto;
    margin: 20px 0;
  }
  .winner-pill {
    display: inline-block;
    background: rgba(201,168,76,0.15);
    border: 1px solid rgba(201,168,76,0.3);
    border-radius: 3px;
    padding: 2px 7px;
    font-size: 12px;
    color: var(--gold-light);
    margin: 2px 2px;
    font-family: 'Arial', sans-serif;
  }
  .winner-pill.repeat {
    background: rgba(139,92,246,0.15);
    border-color: rgba(139,92,246,0.4);
    color: #C4B5FD;
  }
  .nav {
    display: flex;
    gap: 6px;
    padding: 16px 24px;
    background: var(--dark-mid);
    border-bottom: 1px solid var(--border);
    flex-wrap: wrap;
  }
  .nav a {
    font-family: 'Arial', sans-serif;
    font-size: 12px;
    color: var(--text-muted);
    text-decoration: none;
    padding: 4px 10px;
    border-radius: 3px;
    letter-spacing: 0.5px;
  }
  .nav a:hover { color: var(--gold); background: rgba(201,168,76,0.08); }
  .divider { height: 1px; background: var(--border); margin: 24px 0; }
  .tag {
    display: inline-block;
    background: rgba(201,168,76,0.12);
    color: var(--gold);
    font-family: 'Arial', sans-serif;
    font-size: 11px;
    padding: 2px 8px;
    border-radius: 2px;
    margin-right: 6px;
    letter-spacing: 0.5px;
  }
  @media (max-width: 600px) {
    .composer-years { display: none; }
    .composer-name { flex: 0 0 130px; }
  }
</style>
